function o(e){return Number((Number(e)||0).toFixed(2))}function x(e,n){return o(e)>o(n)}function m(e,n){const u=Number(n)||0;return o(Number(e||0)/(1+u/100))}function a(e,n){const u=Number(n)||0;return o(Number(e||0)*(1+u/100))}function b(e,n,u,c){const t=Number(e||0);return u===c?o(t):u==="tax_exclusive"&&c==="tax_inclusive"?a(t,n):m(t,n)}function f(e,n,u,c){const t=Number(e||0);if(u==="tax_inclusive"){const r=o(t);return{invoiceAmountExcl:m(r,n),totalIncl:r}}const s=o(t);let i=a(s,n);const l=c?.maxTotalIncl;if(l!=null&&Number.isFinite(l)&&l>=0){const r=o(l),v=o(i-r);if(i>r&&v<=.01)return{invoiceAmountExcl:m(r,n),totalIncl:r}}return{invoiceAmountExcl:s,totalIncl:i}}function N(e,n,u,c){const t=Number(e||0),s=Number(n),i=Number(u);if(!(t>0)||s===i||c==="tax_inclusive")return o(t);const l=a(t,s);return m(l,i)}export{N as a,b as c,m as i,x as m,f as r};
